<script setup lang="ts">
import{ref}from'vue';import{api,apiMessage}from'@/api/client';
const fileName=ref('');const payload=ref<unknown>(null);const message=ref('');const error=ref('');
async function choose(event:Event){const file=(event.target as HTMLInputElement).files?.[0];if(!file)return;fileName.value=file.name;try{payload.value=JSON.parse(await file.text());error.value='';}catch{payload.value=null;error.value='JSON 文件无法解析。';}}
async function upload(){if(!payload.value)return;try{const{data}=await api.post('/migrations/legacy-snapshot',payload.value);message.value=`已保存快照 ${data.snapshotId}，包含 ${data.progressRecords} 条进度记录。`;error.value='';}catch(e){error.value=apiMessage(e);}}
</script>
<template><div class="page"><section class="page-head"><div><p class="eyebrow">SETTINGS / MIGRATION</p><h1>设置与旧数据迁移</h1></div><p>先完整保存旧版 JSON，再分阶段转为关系型数据。</p></section><section class="section settings-grid"><div><strong class="panel-number">01</strong><h2>旧版数据快照</h2><p>从 1.8.3 的“设置与备份”导出 JSON，然后在这里上传。服务器会原样保存，避免迁移期间丢失。</p></div><div class="upload-box"><label class="file-button">选择 JSON<input type="file" accept="application/json,.json" @change="choose"/></label><strong>{{fileName||'尚未选择文件'}}</strong><button class="btn primary" :disabled="!payload" @click="upload">上传到服务器</button><p v-if="message" class="success-text">{{message}}</p><p v-if="error" class="error-text">{{error}}</p></div></section><section class="section"><strong class="panel-number">02</strong><h2>客户端路线</h2><div class="roadmap"><article><strong>Web</strong><p>Vue 3 当前实现，作为所有客户端的业务基准。</p></article><article><strong>Windows / macOS</strong><p>后续使用 Tauri 封装 Web 前端并调用同一 API。</p></article><article><strong>Android</strong><p>后续使用 Capacitor 或原生 Kotlin 客户端。</p></article><article><strong>微信小程序</strong><p>使用独立 UI 层复用 REST API 与账号体系。</p></article></div></section></div></template>
